actions.script:
import org.moqui.context.ExecutionContext
ExecutionContext ec = context.ec
def fromD = (filterDate ?: ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd'))
def thruD = (filterThruDate ?: fromD)
def ds = java.sql.Timestamp.valueOf(fromD + ' 00:00:00'); def de = java.sql.Timestamp.valueOf(thruD + ' 23:59:59')
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def ef = ec.entity.find("zenith.erp.pos.PosExpenseView").condition("expenseDate","greater-equals",ds).condition("expenseDate","less-equals",de).orderBy("-expenseDate")
if (filterCategoryId) ef.condition("categoryId", filterCategoryId)
if (_org) ef.condition("organizationPartyId", _org)
def rows = ef.list()
def stx = (searchText ?: '').trim().toLowerCase()
if (stx) rows = rows.findAll { ((it.description ?: '').toLowerCase().contains(stx) || (it.referenceNumber ?: '').toLowerCase().contains(stx) || ("${it.firstName ?: ''} ${it.lastName ?: ''}".toLowerCase().contains(stx))) }
def esc = { v -> if (v == null) return ""; String s = v.toString().trim(); (s.contains(",")||s.contains("\"")||s.contains("\n")) ? "\"" + s.replace("\"","\"\"") + "\"" : s }
def num = { v -> String.format("%.2f", (v ?: 0.0) as double) }
def dt = { v -> v == null ? "" : ec.l10n.format(v, 'dd MMM yyyy HH:mm') }
StringBuilder csv = new StringBuilder()
csv.append("ZetaERP - Expenses Report\n")
csv.append("Period: ${fromD} to ${thruD}  |  Generated: ${ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')}\n\n")
csv.append("Date,Category,Description,Amount,Payment,Ref No.,Entered By\n")
rows.each { r -> csv.append("${dt(r.expenseDate)},${esc(r.categoryName)},${esc(r.description)},${num(r.amount)},${esc(r.paymentMethod)},${esc(r.referenceNumber)},${esc(("${r.firstName ?: ''} ${r.lastName ?: ''}").trim())}\n") }
ec.web.sendTextResponse(csv.toString(), "text/csv", "Expenses_${ec.l10n.format(ec.user.nowTimestamp, 'yyyyMMdd_HHmm')}.csv")

def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def num2 = { v -> zinr.inr(ec.l10n.format((v ?: 0) as BigDecimal, '#,##0.00')) }

// search filter (description / ref / entered-by)
def stx = (searchText ?: '').trim().toLowerCase()
expenseList = stx ? expenseListRaw.findAll { ((it.description ?: '').toLowerCase().contains(stx) || (it.referenceNumber ?: '').toLowerCase().contains(stx) || ("${it.firstName ?: ''} ${it.lastName ?: ''}".toLowerCase().contains(stx))) } : expenseListRaw

// per-category stable colour: donut hex + matching zenith-badge class for the table pill
def _badgeNames = ['primary','success','info','warning','danger','grey']
def _badgeHex   = ['#7C3AED','#10B981','#2563EB','#D97706','#DC2626','#6B7280']
categoryColorMap = [:]; categoryBadgeMap = [:]
categoryList.eachWithIndex { c, i -> def k = i % 6; categoryColorMap[c.categoryName] = _badgeHex[k]; categoryBadgeMap[c.categoryName] = _badgeNames[k] }

// ---- Month / today stats (org-scoped, independent of the on-screen filter) ----
def _cm = java.util.Calendar.getInstance(); _cm.setTime(nowTs); _cm.set(java.util.Calendar.DAY_OF_MONTH, 1)
def thisMonthStart = new java.sql.Timestamp(_cm.getTimeInMillis())
def _lm = java.util.Calendar.getInstance(); _lm.setTime(nowTs); _lm.set(java.util.Calendar.DAY_OF_MONTH, 1); _lm.add(java.util.Calendar.MONTH, -1)
def lastMonthStart = new java.sql.Timestamp(_lm.getTimeInMillis())
def lastMonthEnd = new java.sql.Timestamp(thisMonthStart.getTime() - 1000)
def dayNum = java.util.Calendar.getInstance(); dayNum.setTime(nowTs)
def daysElapsed = dayNum.get(java.util.Calendar.DAY_OF_MONTH)
def _mf = ec.entity.find("zenith.erp.pos.PosExpense").condition("expenseDate","greater-equals",thisMonthStart).condition("expenseDate","less-equals",nowTs)
if (_org) _mf.condition("organizationPartyId", _org)
def _monthList = _mf.list()
def thisMonthTotal = _monthList.sum { (it.amount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
def totalTxns = _monthList.size()
def _lf = ec.entity.find("zenith.erp.pos.PosExpense").condition("expenseDate","greater-equals",lastMonthStart).condition("expenseDate","less-equals",lastMonthEnd)
if (_org) _lf.condition("organizationPartyId", _org)
def lastMonthTotal = _lf.list().sum { (it.amount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
def _todayS = java.sql.Timestamp.valueOf(sdf.format(nowTs) + ' 00:00:00'); def _todayE = java.sql.Timestamp.valueOf(sdf.format(nowTs) + ' 23:59:59')
def _todayList = _monthList.findAll { it.expenseDate != null && it.expenseDate >= _todayS && it.expenseDate <= _todayE }
def todayTotal = _todayList.sum { (it.amount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
def todayCount = _todayList.size()
def avgDaily = daysElapsed > 0 ? (thisMonthTotal / daysElapsed).setScale(2, java.math.RoundingMode.HALF_UP) : BigDecimal.ZERO
def monthDelta = lastMonthTotal > 0 ? ((thisMonthTotal - lastMonthTotal) * 100 / lastMonthTotal) : (thisMonthTotal > 0 ? 100.0G : 0.0G)
monthLabel = new java.text.SimpleDateFormat('MMM yyyy').format(nowTs)
def _mdUp = monthDelta >= 0
monthDeltaHtml = '<span style="color:'+(_mdUp?'#DC2626':'#059669')+';font-weight:700">'+(_mdUp?'&#8593; ':'&#8595; ')+ec.l10n.format(monthDelta.abs(),'#0.0')+'%</span>'
// (for expenses an INCREASE is red/bad, a decrease green/good)
pendingApprovals = 0   // no approval workflow on PosExpense -> nothing pending

// ---- Budget (real, from the user's own preference; never fabricated) ----
def _budRaw = null; try { _budRaw = ec.user.getPreference('POS_EXP_BUDGET') } catch (Exception e) {}
budgetVal = null; try { budgetVal = (_budRaw) ? new BigDecimal(_budRaw) : null } catch (Exception e) { budgetVal = null }
budgetPct = (budgetVal != null && budgetVal > 0) ? Math.min(100.0, (thisMonthTotal * 100 / budgetVal).doubleValue()) : null

// ---- Category breakdown (donut) from the filtered list ----
def _catMap = new LinkedHashMap()
expenseList.each { def k = (it.categoryName ?: 'Uncategorised'); _catMap[k] = (_catMap[k] ?: 0.0G) + ((it.amount ?: 0) as BigDecimal) }
filteredTotal = _catMap.values().inject(0.0G) { a, v -> a + (v as BigDecimal) }
def _ft = filteredTotal > 0 ? filteredTotal : 1.0G
def _catSorted = _catMap.entrySet().sort { -(it.value as BigDecimal) }
def _cum = 0.0; def _donut = new StringBuilder()
categoryBreakdown = []
_catSorted.each { e ->
    def amt = e.value as BigDecimal; def pctExact = (amt * 100.0 / _ft).doubleValue(); def col = categoryColorMap[e.key] ?: '#9CA3AF'
    categoryBreakdown.add([name:e.key, amt:'₹'+num2(amt), pct:ec.l10n.format(amt*100/_ft, '#0.0'), color:col])
    _donut.append('<circle cx="70" cy="70" r="52" fill="none" stroke="'+col+'" stroke-width="17" pathLength="100" stroke-dasharray="'+String.format('%.2f',pctExact)+' 100" stroke-dashoffset="'+String.format('%.2f',-_cum)+'" transform="rotate(-90 70 70)"/>')
    _cum += pctExact
}
expenseDonutSvg = '<svg width="170" height="170" viewBox="0 0 140 140">' + (_donut.length()>0 ? _donut.toString() : '<circle cx="70" cy="70" r="52" fill="none" stroke="#EEF0F5" stroke-width="17"/>') + '</svg>'
filteredTotalStr = '₹' + num2(filteredTotal)

// ---- Trend (daily totals across the filter range, capped) ----
def _fS = java.sql.Timestamp.valueOf(filterDate + ' 00:00:00')
def _fE = java.sql.Timestamp.valueOf(filterThruDate + ' 23:59:59')
def _days = Math.min(31L, Math.max(1L, (long)(((_fE.getTime() - _fS.getTime()) / (1000L*60*60*24)) + 1)))
def _buckets = new BigDecimal[(int)_days]; for (int i=0;i<_days;i++) _buckets[i]=0.0G
def _labels = []
def _lblFmt = new java.text.SimpleDateFormat(_days <= 8 ? 'EEE' : 'dd')
def _cal2 = java.util.Calendar.getInstance(); _cal2.setTime(new java.util.Date(_fS.getTime()))
for (int i=0;i<_days;i++) { _labels.add(_lblFmt.format(_cal2.getTime())); _cal2.add(java.util.Calendar.DAY_OF_MONTH, 1) }
expenseList.each { def d = it.expenseDate; if (d != null) { def idx = (int)(((d.getTime() - _fS.getTime()) / (1000L*60*60*24))); if (idx >= 0 && idx < _days) _buckets[idx] += ((it.amount ?: 0) as BigDecimal) } }
def _tmax = 0.0G; for (int i=0;i<_days;i++) if (_buckets[i] > _tmax) _tmax = _buckets[i]
if (_tmax <= 0) _tmax = 1.0G
double _TW=640.0, _TH=200.0, _tbx=44.0, _tby=168.0; double _tpw=_TW-_tbx-12, _tph=_tby-14
def _tf = { double v -> String.format('%.1f', v) }
def _tpts = []; for (int i=0;i<_days;i++) { double x=_tbx+(_days>1?(i*_tpw/(_days-1)):_tpw/2); double y=_tby-((_buckets[i].doubleValue()/_tmax.doubleValue())*_tph); _tpts.add([x:x,y:y]) }
def _tline = _tpts.collect { _tf(it.x)+','+_tf(it.y) }.join(' ')
def _tarea = 'M'+_tf(_tpts[0].x)+','+_tf(_tby)+' L'+_tpts.collect{ _tf(it.x)+','+_tf(it.y) }.join(' L')+' L'+_tf(_tpts[-1].x)+','+_tf(_tby)+' Z'
def _tgrid = new StringBuilder(); for (int t=0;t<=5;t++){ double frac=t/5.0; double yv=_tby-frac*_tph; def val=_tmax*frac
    def lbl = '₹'+(val>=1000 ? (String.format('%.0f',(val/1000).doubleValue())+'K') : String.format('%.0f',val.doubleValue()))
    _tgrid.append('<line x1="'+_tf(_tbx)+'" y1="'+_tf(yv)+'" x2="'+_tf(_TW-12)+'" y2="'+_tf(yv)+'" stroke="#F1F5F9" stroke-width="1"/>')
    _tgrid.append('<text x="'+_tf(_tbx-6)+'" y="'+_tf(yv+3)+'" font-size="9" fill="#9CA3AF" text-anchor="end">'+lbl+'</text>') }
def _txl = new StringBuilder(); _tpts.eachWithIndex { pt, i -> if (_days<=14 || i%Math.ceil(_days/10)==0) _txl.append('<text x="'+_tf(pt.x)+'" y="'+_tf(_tby+15)+'" font-size="9" fill="#9CA3AF" text-anchor="middle">'+_labels[i]+'</text>') }
def _tdots = new StringBuilder(); _tpts.each { if (it.y < _tby) _tdots.append('<circle cx="'+_tf(it.x)+'" cy="'+_tf(it.y)+'" r="3" fill="#EF4444"/>') }
expenseTrendSvg = '<svg viewBox="0 0 '+((int)_TW)+' '+((int)_TH)+'" preserveAspectRatio="xMidYMid meet" style="width:100%;height:auto;min-width:520px">'+_tgrid.toString()+'<path d="'+_tarea+'" fill="#EF4444" fill-opacity="0.09"/><polyline points="'+_tline+'" fill="none" stroke="#EF4444" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>'+_tdots.toString()+_txl.toString()+'</svg>'
trendTotalStr = '₹' + num2(filteredTotal)

// ---- Stat cards (5 icon cards; budget rendered separately) ----
def _ic = { d -> '<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'+d+'</svg>' }
expStatCards = [
  [val:'₹'+num2(thisMonthTotal), label:'This Month ('+monthLabel+')', meta:'vs last month '+monthDeltaHtml, icon:_ic('<polyline points="22 7 13.5 15.5 8.5 10.5 2 17"/><polyline points="16 7 22 7 22 13"/>'), bg:'#F5F3FF', ac:'#7C3AED', ib:'#EDE9FE'],
  [val:'₹'+num2(todayTotal), label:"Today's Expense", meta:todayCount+' transaction'+(todayCount==1?'':'s'), icon:_ic('<path d="M19 7V4a1 1 0 0 0-1-1H5a2 2 0 0 0 0 4h15a1 1 0 0 1 1 1v4"/><path d="M3 5v14a2 2 0 0 0 2 2h15a1 1 0 0 0 1-1v-4"/><path d="M18 12a2 2 0 0 0 0 4h4v-4Z"/>'), bg:'#FEF2F2', ac:'#DC2626', ib:'#FEE2E2'],
  [val:'₹'+num2(avgDaily), label:'Avg. Daily Expense', meta:'This Month', icon:_ic('<path d="M22 12h-4l-3 9L9 3l-3 9H2"/>'), bg:'#FFFBEB', ac:'#D97706', ib:'#FEF3C7'],
  [val:totalTxns.toString(), label:'Total Transactions', meta:'This Month', icon:_ic('<path d="M8 2v4"/><path d="M16 2v4"/><rect width="18" height="18" x="3" y="4" rx="2"/><path d="M3 10h18"/>'), bg:'#EFF6FF', ac:'#2563EB', ib:'#DBEAFE'],
  [val:pendingApprovals.toString(), label:'Pending Approvals', meta:(pendingApprovals==0?'Nothing pending':'Requires your review'), icon:_ic('<rect width="8" height="4" x="8" y="2" rx="1"/><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"/><path d="m9 14 2 2 4-4"/>'), bg:'#ECFDF5', ac:'#059669', ib:'#D1FAE5']
]
thisMonthTotalStr = '₹' + num2(thisMonthTotal)
budgetValStr = budgetVal != null ? ('₹' + num2(budgetVal)) : null
